'use strict';
let foundationOwner=null,foundationEpoch=0,foundationData=null,foundationBusy=false,foundationError='',foundationSyncing=false,foundationTimer=null,foundationDraftQueue=Promise.resolve();
function foundationReset(){document.documentElement?.classList?.remove('foundation-mode');foundationOwner=null;++foundationEpoch;foundationData=null;foundationBusy=false;foundationSyncing=false;foundationError='';clearTimeout(foundationTimer)}
function foundationNode(key){return key?.startsWith('word:')?'sense:'+key.slice(5):key?.startsWith('grammar:')?key.slice(8):'lesson:'+key}
function foundationFrame(p){return p?.theme==='work'?'Could you send me ____, please? / Thank you for ____.':p?.theme==='travel'?"I'd like ____, please. / Where is ____?":p?.theme==='campus'?'Could you explain ____, please? / I study ____.':'I noticed ____. / I think ____ because ____.'}
async function openFoundation(key,review=false){if(typeof flowGuardLeave==='function'&&!flowGuardLeave())return;if(typeof flowStash==='function')flowStash();view='journey';if(typeof flowTask!=='undefined')flowTask=null;stopRecording();const owner=user.id,epoch=++foundationEpoch;foundationOwner=owner;foundationSyncing=false;foundationData=null;foundationError='';shell(pagehead('一步一句，接着学','每次完成一个小步骤。')+'<p role="status">正在打开小课程…</p>');try{const d=await api('foundation/lesson?id='+encodeURIComponent(key));if(user?.id!==owner||epoch!==foundationEpoch||view!=='journey')return;d.review=review&&d.step>=3;d.reviewAnswer=typeof flowRestoreText==='function'?flowRestoreText('foundation-review',key,''):'';if(d.step===2&&typeof flowRestoreText==='function'){d.savedAnswer=d.answer;d.answer=flowRestoreText('foundation',key,d.answer||'',d.updated||0);}foundationData=d;if(typeof flowPoint==='function')flowPoint({type:'foundation',key,review:d.review});renderFoundation();if(d.step===2&&!d.review)foundationSync()}catch(e){if(user?.id===owner&&epoch===foundationEpoch)shell(pagehead('暂时没有打开课程','已保存的进度仍在。')+`<section class="card continuity-error" role="alert"><p>${esc(e.message)}</p><button class="btn" data-foundation-lesson="${esc(key)}" ${review?'data-foundation-review="1"':''}>在这里重试 →</button><button class="text-button" data-view="home">回到私教</button></section>`)}}
function foundationSaveStatus(){if(!foundationData)return '';const local=typeof flowLocalGet==='function'?flowLocalGet('foundation',foundationData.lesson):null;return foundationSyncing?'正在同步，当前输入已留在此页':foundationError||local?(typeof flowStorageOK!=='undefined'&&!flowStorageOK?'本机存储不可用，请保存成果后再关闭':'本机已保留，等待同步'):'进度已同步'}
function renderFoundation(){const d=foundationData;if(!d)return;const done=d.step>=3&&!d.review;const next=d.next;const error=foundationError?`<div class="continuity-error" role="alert">${esc(foundationError)}</div>`:'';const controls=done?`<h2>这一次，你完成了：</h2><blockquote lang="en">${esc(d.answer)}</blockquote><p>有支持的学习已保存，尚不代表独立运用。课程复习会继续提醒。</p>${d.due?`<p class="small muted">下次复习：${esc(new Date(d.due*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</p>`:''}<div class="actions">${next?.optional?'<button class="btn" data-foundation-stage="1">进入下一组听说读写 →</button>':''}${next?`<button class="btn" data-foundation-lesson="${esc(next.lesson)}" ${next.review?'data-foundation-review="1"':''}>${esc(next.title)} →</button>`:`<button class="btn" data-foundation-lesson="${esc(d.lesson)}" data-foundation-review="1">再回忆这一句 →</button>`}<button class="quiet-button" data-view="home">今天完成，回到私教</button></div><button class="text-button" data-flow-node="${esc(foundationNode(d.lesson))}">查看这句话的知识连接 →</button>`:d.review?`<p>先不看例句，回忆这句表达：${esc(d.review_meaning||d.meaning)}</p><button class="text-button" data-foundation-hint="1">需要时查看目标表达</button>${d.hint?`<blockquote lang="en">${esc(d.target)}</blockquote>`:''}<form id="foundation-form"><label for="foundation-answer">写出本课练过的表达</label><textarea id="foundation-answer" name="answer" rows="3" maxlength="1200" required>${esc(d.reviewAnswer||'')}</textarea><button class="btn" ${foundationBusy?'disabled':''}>保存这次复习</button></form>`:`<div class="foundation-example"><h2>${esc(d.meaning)}</h2><blockquote lang="en">${esc(d.example)}</blockquote><button class="quiet-button" data-foundation-listen="1">听一句并跟读 ▷</button><p>${esc(d.contrast)}</p></div>${d.step===0?'<button class="btn" data-foundation-read="1">我已看过例句，继续练习 →</button>':d.step===1?`<form id="foundation-form"><fieldset><legend>${esc(d.prompt)}</legend>${d.options.map((o,i)=>`<label class="foundation-choice"><input type="radio" name="answer" value="${i}" required>${esc(o)}</label>`).join('')}</fieldset><button class="btn" ${foundationBusy?'disabled':''}>检查这一步</button></form>`:`<form id="foundation-form"><label for="foundation-answer">${esc(d.write_prompt||'练指定表达（也接受常见缩写）：'+d.target)}</label><textarea id="foundation-answer" name="answer" rows="3" maxlength="1200" required placeholder="对照目标表达完成这一小步">${esc(d.answer||'')}</textarea><p class="small muted">目标表达：${esc(d.target)}</p><p id="foundation-sync" role="status">${esc(foundationSaveStatus())}</p><button class="btn" ${foundationBusy?'disabled':''}>保存学习成果</button></form>`}`;
shell(pagehead(d.title,d.review?'复习这一句，逐步减少帮助。':done?'学习已保存，选择下一小步或安心休息。':'先看懂，再练习，最后自己写。')+`<section class="card foundation-lesson" aria-label="基础微课"><div class="session-progress"><span>${done?'本课已完成':d.review?'课程复习':`第 ${d.step+1} / 3 步`}</span><span>约3分钟 · 可随时暂停</span></div>${controls}${error}<p class="small muted">${esc(d.note)}</p></section>${done?'':'<button class="text-button" data-view="home">暂停一下，稍后继续 →</button>'}`)}
async function foundationSync(){const d=foundationData;if(!d||d.step!==2||d.review||!user||foundationSyncing)return;const owner=user.id,epoch=foundationEpoch,key=d.lesson,local=typeof flowLocalGet==='function'?flowLocalGet('foundation',key):null;if(!local)return;foundationSyncing=true;let failed=false;try{await api('foundation/draft',{lesson:key,answer:local.answer,revision:Math.max(local.revision,d.revision+1)});d.savedAnswer=local.answer;if(user?.id===owner&&typeof flowLocalDrop==='function')flowLocalDrop('foundation',key,local.answer,owner)}catch{failed=true;if(user?.id===owner)foundationError='网络暂时不可用，文字保留在本机。恢复连接后可继续同步。'}finally{if(epoch===foundationEpoch)foundationSyncing=false;if(user?.id===owner&&epoch===foundationEpoch){const n=document.querySelector('#foundation-sync');if(n)n.textContent=foundationSaveStatus();if(!failed&&typeof flowLocalGet==='function'&&flowLocalGet('foundation',key))foundationTimer=setTimeout(foundationSync,350)}}}
async function foundationSubmit(answer){if(foundationBusy||!foundationData)return;const owner=user.id,epoch=foundationEpoch,lesson=foundationData.lesson,step=foundationData.step;foundationBusy=true;foundationError='';try{const review=foundationData.review;const r=await api(review?'foundation/review':'foundation/step',{lesson,step,answer,...(review?{request_id:foundationData.reviewRequest||(foundationData.reviewRequest=flowRequestId())}:{})});if(user?.id!==owner||epoch!==foundationEpoch||view!=='journey')return;if(r.ok){foundationBusy=false;if(typeof flowLocalDrop==='function'){flowLocalDrop('foundation',lesson);if(review)flowLocalDrop('foundation-review',lesson);}if(r.next&&typeof flowPoint==='function')flowPoint({type:'foundation',key:r.next.lesson,review:r.next.review});foundationData=review?{...foundationData,review:false,answer,due:r.due,next:r.next}:{...r.current,next:r.next};renderFoundation()}else{foundationError=r.message;const n=document.querySelector('.continuity-error');if(n)n.textContent=r.message;else document.querySelector('.foundation-lesson')?.insertAdjacentHTML('beforeend',`<p class="continuity-error" role="alert">${esc(r.message)}</p>`)}}catch(e){if(user?.id===owner&&epoch===foundationEpoch){if(e.status===409){try{const d=e.payload?.current||await api('foundation/lesson?id='+encodeURIComponent(lesson));foundationData={...d,answer:d.step===2?(typeof flowRestoreText==='function'?flowRestoreText('foundation',lesson,d.answer):d.answer):d.answer};foundationError='已找回最新进度，可以继续。';foundationBusy=false;renderFoundation()}catch{foundationError='恢复进度时连接中断，请保留输入后再提交。'}}else{foundationError=e.message;document.querySelector('.foundation-lesson')?.insertAdjacentHTML('beforeend',`<p class="continuity-error" role="alert">${esc(e.message)} 当前输入保留，可以重试。</p>`)}}}finally{foundationBusy=false}}
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!user)return;try{if(b.dataset.foundationLesson)await openFoundation(b.dataset.foundationLesson,!!b.dataset.foundationReview);if(b.dataset.foundationRead)await foundationSubmit('');if(b.dataset.foundationHint&&foundationData){foundationData.hint=true;renderFoundation()}if(b.dataset.foundationListen&&foundationData){try{studioSpeak(foundationData.example)}catch{foundationError='当前设备暂不能朗读，可以先看中英例句继续练习。';renderFoundation()}}if(b.dataset.foundationStage&&foundationData){const owner=user.id,epoch=foundationEpoch;b.disabled=true;try{await api('growth/stage',{request_id:foundationData.stageRequest||(foundationData.stageRequest=flowRequestId()),replace:false});if(user?.id===owner&&epoch===foundationEpoch&&view==='journey')await coachLoad()}finally{if(b.isConnected)b.disabled=false}}if(b.dataset.foundationMode){const owner=user.id;await api('foundation/mode',{mode:b.dataset.foundationMode});if(user?.id===owner){studioCatalog=null;await coachLoad()}}}catch(err){toast(err.message)}});
app.addEventListener('submit',e=>{if(e.target.id!=='foundation-form')return;e.preventDefault();foundationSubmit(String(new FormData(e.target).get('answer')||''))});
app.addEventListener('input',e=>{if(e.target.id!=='foundation-answer'||!user||!foundationData)return;if(foundationData.review){foundationData.reviewAnswer=e.target.value;foundationData.reviewRequest=null;if(typeof flowLocalPut==='function')flowLocalPut('foundation-review',foundationData.lesson,e.target.value);return}foundationData.answer=e.target.value;foundationError='';if(typeof flowLocalPut==='function')flowLocalPut('foundation',foundationData.lesson,e.target.value);clearTimeout(foundationTimer);foundationTimer=setTimeout(foundationSync,350);const n=document.querySelector('#foundation-sync');if(n)n.textContent=foundationSaveStatus()});
function foundationLaunchHTML(){return `<section class="card foundation-launch"><h2>先学会一句，今天就能用。</h2><p>先看中英对照、听一句，再完成替换。每次约3分钟，可以分次继续。</p><div class="actions"><button class="btn" data-foundation-lesson="food">从点餐短句开始 →</button><button class="quiet-button" data-foundation-lesson="directions">学一句问路</button><button class="quiet-button" data-foundation-lesson="hotel">说明自己有预订</button><button class="quiet-button" data-foundation-lesson="work-request">工作邮件请求</button><button class="quiet-button" data-foundation-lesson="campus-help">请求重复说明</button></div><p class="small muted">完成基础课后可继续普通语料；基础课不是A1或A2能力认证。</p></section>`}
const foundationOriginalPractice=practiceHTML;
practiceHTML=function(d){const original=foundationOriginalPractice(d);return studioCatalog?.foundation_basic?foundationLaunchHTML()+'<details class="foundation-explore"><summary>探索普通分级语料（A2起步，可稍后使用）</summary>'+original+'</details>':original};
const foundationOriginalCatalog=renderStudioCatalog;
renderStudioCatalog=function(){foundationOriginalCatalog();if(studioCatalog?.foundation_basic){const slot=document.querySelector('#practice-slot');if(slot?.nextElementSibling){const explore=document.createElement('details');explore.className='foundation-explore';const summary=document.createElement('summary');summary.textContent='探索全部材料与筛选（可以稍后再用）';explore.append(summary);while(slot.nextElementSibling)explore.append(slot.nextElementSibling);slot.after(explore)}}};
const foundationOriginalStudio=renderStudioPack;
renderStudioPack=function(){const original=studioPack?.writing;if(studioCatalog?.foundation_basic&&studioSkill==='writing')studioPack.writing='先用自己的信息写1–2句，不要求现在完成整段。可以对照下面的句框，再逐步去掉帮助。';foundationOriginalStudio();if(studioPack&&original!==undefined)studioPack.writing=original;if(!studioCatalog?.foundation_basic||!['writing','speaking'].includes(studioSkill))return;const field=document.querySelector('#studio-answer');if(!field)return;const panel=document.createElement('section');panel.className='foundation-scaffold card';panel.innerHTML='<h3>先用一个相关句框。</h3><p lang="en">'+esc(foundationFrame(studioPack))+'</p><p class="small muted">替换成自己的信息，先写1–2句。使用支架属于有支持的练习。</p>';field.parentElement.before(panel)};
const foundationOriginalCoach=typeof renderCoach==='function'?renderCoach:null;
if(foundationOriginalCoach)renderCoach=function(){foundationOriginalCoach();document.documentElement?.classList?.toggle('foundation-mode',!!coachData?.foundation?.basic);const resume=typeof flowResumeHTML==='function'?flowResumeHTML():'';if(coachPanel==='chat'){const recent=coachData?.foundation?.recent||[];const links=recent.length?'<details class="card foundation-connections"><summary>刚练过的表达与知识连接</summary>'+recent.map(r=>`<div class="lesson-record"><div><blockquote lang="en">${esc(r.answer)}</blockquote><small>有支持的练习 · 独立运用待验证</small></div><button class="text-button" data-flow-node="${esc(foundationNode(r.lesson))}">查看知识连接 →</button></div>`).join('')+'</details>':'';if(resume)document.querySelector('.mentor-tabs')?.insertAdjacentHTML('afterend',resume);if(links)document.querySelector('.loop-home')?.insertAdjacentHTML('afterend',links)}};
